var report=new{status=failures.Count==0?"passed":"failed",failures,deviceTypes=bt.Values.Count(t=>t.FullName.StartsWith("HandheldCompanion.Devices.")),layoutRows,initializerClosure=sideEffects,initializerClosureCount=sideEffects.Count,implicitTypeInitializersFollowed=true,initializerExecution=false,initializerILComparedSeparately="retained-IL report",missingInternalReferences=missingRefs,reflectionAndSerializerSites=dynamicSites,stringLiterals=literals,removedTypes=bt.Keys.Except(at.Keys).Order(),removedMethods=bt.Values.SelectMany(t=>t.Methods).Where(m=>!at.TryGetValue(m.DeclaringType.FullName,out var c)||!c.Methods.Any(x=>x.FullName==m.FullName&&x.GenericParameters.Count==m.GenericParameters.Count)).Select(m=>m.FullName).Order(),potentialUnusedAssemblyReferences=before.MainModule.AssemblyReferences.Select(a=>a.FullName).Except(after.MainModule.AssemblyReferences.Select(a=>a.FullName)).Order(),reflectionCompletenessProven=false,hardwareAccess=false};File.WriteAllText(args[2],JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(new{report.status,initializers=report.initializerClosureCount,missingReferences=missingRefs.Count,failures=failures.Count,reflectionSites=dynamicSites.Count}));if(failures.Count>0)Environment.ExitCode=1;

